from cardio_1 import a, G
# I27 — Hypertension pulmonaire, cœur pulmonaire chronique et maladies des vaisseaux pulmonaires (P-02-Pneumologie)
a('HTP',[('H','Hyper'),('T','Tension'),('P','Pulmonaire')],'Hypertension pulmonaire','<p>Pression artérielle pulmonaire moyenne supérieure à 20 mmHg au repos, mesurée par cathétérisme cardiaque droit (ESC/ERS 2022). Terme générique qui couvre les cinq groupes.</p>','i27-def')
a('HTP-TEC',[('HTP','Hypertension Pulmonaire'),('T','Thrombo-'),('E','Embolique'),('C','Chronique')],'Hypertension pulmonaire thromboembolique chronique','<p>Groupe 4 : obstruction des artères pulmonaires par des caillots organisés en tissu fibreux, persistant après au moins trois mois d’anticoagulation efficace. Codage CIM-10-GM I27.20.</p>','i27-cteph')
a('PAPm',[('P','Pression'),('A','Artérielle'),('P','Pulmonaire'),('m','moyenne')],'Pression artérielle pulmonaire moyenne','<p>Moyenne de la pression dans l’artère pulmonaire sur un cycle cardiaque. Normale de 8 à 20 mmHg au repos ; une valeur supérieure à 20 mmHg définit l’hypertension pulmonaire.</p>','i27-def')
a('PAPO',[('P','Pression'),('A','Artérielle'),('P','Pulmonaire'),('O','d’Occlusion')],'Pression artérielle pulmonaire d’occlusion','<p>Pression mesurée avec le ballonnet du cathéter gonflé dans une branche de l’artère pulmonaire ; elle reflète la pression de l’oreillette gauche. Seuil de 15 mmHg entre formes précapillaire et postcapillaire.</p>','i27-papo')
a('EFR',[('E','Épreuves'),('F','Fonctionnelles'),('R','Respiratoires')],'Épreuves fonctionnelles respiratoires','<p>Ensemble de la spirométrie, de la mesure des volumes pulmonaires et de la diffusion du monoxyde de carbone.</p>')
a('BMPR2',[('BMP','Bone Morphogenetic Protein (protéine morphogénétique osseuse)'),('R','Receptor (récepteur)'),('2','de type 2')],'Gène du récepteur de type 2 des protéines morphogénétiques osseuses','<p>Gène dont les variants pathogènes, autosomiques dominants à pénétrance incomplète, causent la majorité des HTAP héréditaires.</p>','i27-bmpr2')
a('BMP',[('B','Bone (os)'),('M','Morphogenetic (morphogénétique)'),('P','Protein (protéine)')],'Protéine morphogénétique osseuse','<p>Facteur de la famille du TGF-β ; dans le poumon, son signal par BMPR2 freine la prolifération des cellules vasculaires.</p>','i27-bmpr2')
a('EIF2AK4',[('EIF2','Eukaryotic Initiation Factor 2 (facteur d’initiation eucaryote 2)'),('A','Alpha'),('K','Kinase'),('4','numéro 4')],'Gène de la kinase 4 de la sous-unité alpha du facteur d’initiation eucaryote 2','<p>Ses variants bialléliques, autosomiques récessifs, causent la maladie veino-occlusive pulmonaire héréditaire.</p>','i27-mvo')
a('TBX4',[('TBX','T-BoX (boîte T, famille de facteurs de transcription)'),('4','numéro 4')],'Gène du facteur de transcription TBX4','<p>Facteur du développement du poumon et des membres inférieurs ; ses variants donnent des HTAP de l’enfant, parfois avec anomalies de la rotule.</p>')
a('SOX17',[('SOX','SRY-related HMG-bOX (boîte HMG apparentée à SRY)'),('17','numéro 17')],'Gène du facteur de transcription SOX17','<p>Facteur endothélial ; ses variants sont associés à l’HTAP, notamment avec cardiopathie congénitale.</p>')
a('KCNK3',[('K','Potassium (K)'),('CN','ChaNnel (canal)'),('K','sous-famille K'),('3','membre 3')],'Gène du canal potassique KCNK3','<p>Canal potassique à deux pores qui fixe le potentiel de membrane des cellules musculaires lisses pulmonaires ; sa perte de fonction favorise la vasoconstriction.</p>')
a('ACVRL1',[('ACVR','ACtiVin Receptor (récepteur de l’activine)'),('L','Like (apparenté)'),('1','de type 1')],'Gène du récepteur apparenté au récepteur de l’activine de type 1 (ALK1)','<p>Récepteur endothélial de BMP9 ; ses variants causent la télangiectasie hémorragique héréditaire de type 2 et parfois une HTAP.</p>','i27-hht')
a('ENG',[('ENG','ENdoGline (abréviation du nom du gène)')],'Gène de l’endogline','<p>Corécepteur endothélial de la famille du TGF-β ; ses variants causent la télangiectasie hémorragique héréditaire de type 1, souvent avec malformations artérioveineuses pulmonaires.</p>','i27-hht')
a('SMAD',[('SMAD','contraction de SMA (gène de Caenorhabditis) et MAD (Mothers Against Decapentaplegic, gène de drosophile)')],'Protéines SMAD','<p>Messagers intracellulaires de la famille du TGF-β : SMAD 1, 5 et 8 transmettent le signal des protéines morphogénétiques osseuses ; SMAD 2 et 3 celui de l’activine et du TGF-β.</p>')
a('SMAD4',[('SMAD','protéine SMAD'),('4','numéro 4')],'Gène SMAD4','<p>Messager commun des voies du TGF-β ; ses variants associent polypose juvénile et télangiectasie hémorragique héréditaire.</p>','i27-hht')
a('ETA',[('ET','EndoThéline'),('A','récepteur de type A')],'Récepteur A de l’endothéline','<p>Récepteur des cellules musculaires lisses ; il transmet la vasoconstriction et la prolifération induites par l’endothéline 1.</p>','i27-d-era')
a('ETB',[('ET','EndoThéline'),('B','récepteur de type B')],'Récepteur B de l’endothéline','<p>Récepteur surtout endothélial ; il libère monoxyde d’azote et prostacycline et participe à la clairance de l’endothéline.</p>','i27-d-era')
a('CYP2C8',[('CYP','CYtochrome P450'),('2C8','famille 2, sous-famille C, isoforme 8')],'Cytochrome P450 2C8','<p>Enzyme hépatique qui transforme le sélexipag ; le gemfibrozil l’inhibe fortement, le clopidogrel modérément.</p>','i27-d-sel')
a('VASCERN',[('VASC','VASCular (vasculaire)'),('ERN','European Reference Network (réseau européen de référence)')],'Réseau européen de référence des maladies vasculaires rares','<p>Réseau de centres experts européens, dont les maladies comprennent la télangiectasie hémorragique héréditaire.</p>')
a('Rendu-Osler',[('Rendu','Henri Rendu, médecin français'),('Osler','William Osler, médecin canadien')],'Maladie de Rendu-Osler','<p>Éponyme de la télangiectasie hémorragique héréditaire.</p>','i27-hht')
a('Swan-Ganz',[('Swan','Jeremy Swan, cardiologue'),('Ganz','William Ganz, cardiologue')],'Cathéter de Swan-Ganz','<p>Cathéter artériel pulmonaire à ballonnet, guidé par le flux, qui mesure les pressions droites, la pression d’occlusion et le débit cardiaque.</p>','i27-kt')
a('Hughes-Stovin',[('Hughes','John Patterson Hughes, médecin britannique'),('Stovin','Peter George Ingle Stovin, médecin britannique')],'Syndrome de Hughes-Stovin','<p>Association rare de thromboses veineuses et d’anévrismes de l’artère pulmonaire, considérée comme proche de la maladie de Behçet.</p>','i27-behcet')
a('Mueller-Mottet',[('Mueller-Mottet','nom d’auteure (Séverine Mueller-Mottet), non développable')],'Mueller-Mottet, première auteure du registre suisse','<p>Publication du registre suisse de l’hypertension pulmonaire, Respiration 2015.</p>')
a('Torres-Rojas',[('Torres-Rojas','nom d’auteure (María Berenice Torres-Rojas), non développable')],'Torres-Rojas, première auteure d’une revue sur l’anévrisme de l’artère pulmonaire','<p>Current Problems in Cardiology 2023.</p>')
# essais
a('AMBITION',[('AMBITION','nom d’essai (AMBrisentan and Tadalafil in patients with pulmonary arterial hypertensION), non strictement lettre à lettre')],'Essai AMBITION (2015)','<p>Ambrisentan et tadalafil d’emblée contre monothérapie chez 500 patients atteints d’HTAP : risque d’échec clinique réduit de moitié.</p>','i27-d-era')
a('SERAPHIN',[('SERAPHIN','nom d’essai (Study with an Endothelin Receptor Antagonist in Pulmonary arterial Hypertension to Improve cliNical outcome), non strictement lettre à lettre')],'Essai SERAPHIN (2013)','<p>Macitentan contre placebo chez 742 patients : réduction de 45 % d’un critère de morbidité et de mortalité avec 10 mg.</p>','i27-d-era')
a('GRIPHON',[('GRIPHON','nom d’essai (prostacyclin [PGI2] Receptor agonist In Pulmonary arterial HypertensiON), non strictement lettre à lettre')],'Essai GRIPHON (2015)','<p>Sélexipag contre placebo chez 1 156 patients : réduction d’environ 40 % d’un critère de morbidité et de mortalité.</p>','i27-d-sel')
a('PATENT-1',[('PATENT','nom d’essai (Pulmonary Arterial hyperTENsion sGC-stimulator Trial), non strictement lettre à lettre'),('1','premier essai')],'Essai PATENT-1 (2013)','<p>Riociguat dans l’HTAP : gain de 36 m au test de marche.</p>','i27-d-rio')
a('CHEST-1',[('CHEST','nom d’essai (Chronic thromboembolic pulmonary Hypertension sGC-Stimulator Trial), non strictement lettre à lettre'),('1','premier essai')],'Essai CHEST-1 (2013)','<p>Riociguat dans l’HTP thromboembolique chronique inopérable ou persistante : gain de 46 m au test de marche.</p>','i27-d-rio')
a('MERIT-1',[('MERIT','nom d’essai (Macitentan in the treatmEnt of inopeRable chronIc thromboembolic pulmonary hyperTension), non strictement lettre à lettre'),('1','premier essai')],'Essai MERIT-1 (2017)','<p>Macitentan dans l’HTP thromboembolique chronique inopérable : baisse des résistances vasculaires pulmonaires.</p>','i27-cteph')
a('CTREPH',[('CTREPH','nom d’essai (Chronic Thromboembolic pulmonary hypertension treated with subcutaneous TREProstinil), non strictement lettre à lettre')],'Essai CTREPH (2019)','<p>Tréprostinil sous-cutané à forte dose dans l’HTP thromboembolique chronique inopérable : amélioration de la distance de marche.</p>','i27-cteph')
a('SUPER-1',[('SUPER','nom d’essai (Sildenafil Use in Pulmonary artERial hypertension), non strictement lettre à lettre'),('1','premier essai')],'Essai SUPER-1 (2005)','<p>Sildénafil contre placebo dans l’HTAP : amélioration de la distance de marche et de l’hémodynamique.</p>','i27-d-pde5')
a('PHIRST',[('PHIRST','nom d’essai (Pulmonary arterial Hypertension and ResponSe to Tadalafil), non strictement lettre à lettre')],'Essai PHIRST (2009)','<p>Tadalafil contre placebo dans l’HTAP : amélioration de la distance de marche avec 40 mg.</p>','i27-d-pde5')
a('INCREASE',[('INCREASE','nom d’essai, non développable lettre à lettre')],'Essai INCREASE (2021)','<p>Tréprostinil inhalé dans l’HTP des pneumopathies interstitielles : gain de 31 m au test de marche à 16 semaines.</p>','i27-d-pgi')
a('STELLAR',[('STELLAR','nom d’essai, non développable lettre à lettre')],'Essai STELLAR (2023)','<p>Sotatercept contre placebo chez 323 patients sous traitement de fond : gain de 40,8 m au test de marche à 24 semaines.</p>','i27-d-sota')
a('ZENITH',[('ZENITH','nom d’essai, non développable lettre à lettre')],'Essai ZENITH (2025)','<p>Sotatercept chez 172 patients à haut risque : réduction de 76 % du critère décès, transplantation ou hospitalisation.</p>','i27-d-sota')
